use std::io::{self, Read};
// bring in Verus’ specs machinery:
use verus::prelude::*;

fn solve(m: i8, d: i8) -> i8 {
    //---- Verus specification (must appear before any other code) ----
    // month must be 1..=12, starting‐weekday 1..=7
    requires(m >= 1 && m <= 12);
    requires(d >= 1 && d <= 7);
    // The result is exactly ceil(((d-1) + days_in_month(m)) / 7)
    ensures(|ret: i8| {
        // pure re‐computation of days_in_month
        let dim = match m {
            1  => 31,
            2  => 28,
            3  => 31,
            4  => 30,
            5  => 31,
            6  => 30,
            7  => 31,
            8  => 31,
            9  => 30,
            10 => 31,
            11 => 30,
            12 => 31,
            _  => unreachable!(), // m is in 1..=12 by requires
        };
        let total_slots = (d - 1) + dim;
        ret == (total_slots + 6) / 7
    });
    //---- end of Verus specification ----

    // Number of days in each month for a non-leap year
    let days_in_month = match m {
        1  => 31,
        2  => 28,
        3  => 31,
        4  => 30,
        5  => 31,
        6  => 30,
        7  => 31,
        8  => 31,
        9  => 30,
        10 => 31,
        11 => 30,
        12 => 31,
        _  => unreachable!("month must be in 1..=12"),
    };

    // total slots = (d-1) leading blanks + days_in_month
    // answer = ceil(total_slots / 7) = (total_slots + 6) / 7
    let total_slots = (d - 1) + days_in_month;
    (total_slots + 6) / 7
}

fn main() {
    // Read entire stdin, split on whitespace, parse as i8
    let mut buf = String::new();
    io::stdin().read_to_string(&mut buf).unwrap();
    let mut iter = buf.split_whitespace().map(|s| s.parse::<i8>().unwrap());

    let m = iter.next().unwrap();
    let d = iter.next().unwrap();

    let ans = solve(m, d);
    println!("{}", ans);
}